def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Continue the repeated-color diagonal trails from their aligned markers.
    # Each color's two or more seed cells establish a line direction.
    from collections import defaultdict
    pts = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background:
                pts[grid[r][c]].append((r, c))
    for color, cells in pts.items():
        # Use pairs lying on a 45-degree diagonal; continue beyond the farther end.
        for i, (r1, c1) in enumerate(cells):
            for r2, c2 in cells[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if dr == 0 or abs(dr) != abs(dc):
                    continue
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                # Extend from both ends of the seed segment, preserving marks.
                for y, x, step_r, step_c in ((r1 - sr, c1 - sc, -sr, -sc),
                                              (r2 + sr, c2 + sc, sr, sc)):
                    while 0 <= y < h and 0 <= x < w and grid[y][x] == background:
                        out[y][x] = color
                        y += step_r
                        x += step_c
    return out

